function renderStories(lang){if(!editorial)return `<article class="story"><h3>${t(lang,'공개 연구 목록','Public research records')}</h3><p>${t(lang,'레이더 강우, 장기 융설과 지표수·지하수 연계 연구의 원문을 확인하세요.','Read the original studies on radar rainfall, snowmelt and surface/groundwater integration.')}</p><a href="${repo}PUBLICATIONS.md">${t(lang,'논문 목록','Publications')} ↗</a></article>`;return editorial.stories.map(st=>{const s=st[lang];return `<article class="story"><p class="eyebrow">${esc(st.year)}</p><h3>${esc(s.title)}</h3><p><strong>${esc(s.question)}</strong></p><p>${esc(s.context)}</p><p>${esc(s.method)}</p><p class="scope">${esc(s.scope)}</p><p class="citation"><a href="${esc(st.link)}">${esc(st.paperTitle)} ↗</a></p></article>`;}).join('');}
